-- data/weaponsources_forever.lua (generated by tools/update-sets.ps1 -Weapons -Forever, nazumods/wow#994) is
-- loaded for real, under both clients: it must leave Retail's weapon sources alone and replace them on Forever
-- only. The generator itself is tested by Tooling/tests/update-sets-forever-weapons.test.ps1; this proves the
-- file it wrote behaves.

describe("Warbandeer_Collected data/weaponsources_forever.lua", function()
  local CATEGORIES = { Quest = true, Vendor = true, ["World Drop"] = true, Crafted = true, ["Trading Post"] = true,
                       Achievement = true, Other = true }

  local function load(flavor)
    _G.tinsert = _G.tinsert or table.insert
    local retail = { { id = 1, types = { [14] = { 7 } } } }
    local ns = { flavor = flavor, WeaponSources = retail }
    assert(loadfile("Warbandeer_Collected/data/weaponsources_forever.lua"))("Warbandeer_Collected", ns)
    return ns, retail
  end

  it("Retail: leaves ns.WeaponSources as it was", function()
    local ns, retail = load({ isRetail = true })
    assert.equals(retail, ns.WeaponSources)
    assert.same({ { id = 1, types = { [14] = { 7 } } } }, ns.WeaponSources)
  end)

  it("a client with no flavor table at all is left alone too", function()
    local ns, retail = load(nil)
    assert.equals(retail, ns.WeaponSources)
  end)

  it("Forever: replaces ns.WeaponSources with Forever's own rows", function()
    local ns, retail = load({ isForever = true })
    assert.not_equals(retail, ns.WeaponSources)
    assert.is_true(#ns.WeaponSources > 0)
    for _, row in ipairs(ns.WeaponSources) do assert.not_equals(1, row.id) end
  end)

  it("Forever: every row is well formed and no appearance is listed twice", function()
    local ns = load({ isForever = true })
    local seen, ids, total = {}, {}, 0
    for _, row in ipairs(ns.WeaponSources) do
      assert.is_number(row.id)
      assert.is_nil(ids[row.id], "row id " .. row.id .. " repeats")
      ids[row.id] = true
      assert.is_string(row.name)
      assert.is_true(CATEGORIES[row.category], "category " .. tostring(row.category))
      assert.is_true(row.release >= 0 and row.release <= 12, "release " .. tostring(row.release))
      assert.is_not_nil(next(row.types), "row " .. row.name .. " has no columns")
      for t, list in pairs(row.types) do
        assert.is_true(t >= 12 and t <= 28, "type " .. tostring(t))
        assert.is_true(#list > 0)
        for _, visual in ipairs(list) do
          assert.is_nil(seen[visual], "visual " .. visual .. " listed twice")
          seen[visual] = true
          total = total + 1
        end
      end
    end
    -- The pinned build (1.60.1.70450) places 996 appearances; a regeneration that changes this is a real change.
    assert.equals(996, total)
  end)
end)
